CustomField.formula:
/*IF( UnitPrice = 0, "", TEXT(FLOOR(UnitPrice)) & "," & LPAD(TEXT(ROUND( (UnitPrice - FLOOR(UnitPrice)) * 100 , 0)), 2, "0") & " €" )
*/
IF( UnitPrice = 0, "", TEXT(ROUND(UnitPrice, 2) - MOD(ROUND(UnitPrice, 2),1)) & "," & LPAD(TEXT(ROUND(MOD(ROUND(UnitPrice, 2),1) * 100,0)), 2, "0") & " €" )
